import {validateMessage} from './validation.js';

describe('specs/hal-engine-conversation-list/spec.md#42', () => {
  it('preserves string and epoch cursors, strips extra fields and rejects malformed cursors', () => {
    const cursors = [
      {sessionId: 's', updatedAt: '2026-01-01T00:00:00.000Z'},
      {sessionId: 's'.repeat(128), updatedAt: 0},
    ];
    const invalid = [
      null,
      [],
      'cursor',
      {},
      {sessionId: '', updatedAt: 0},
      {sessionId: 's'.repeat(129), updatedAt: 0},
      {sessionId: 1, updatedAt: 0},
      {sessionId: 's'},
      {sessionId: 's', updatedAt: 'not-a-date'},
      {sessionId: 's', updatedAt: true},
      {sessionId: 's', updatedAt: null},
      {sessionId: 's', updatedAt: Infinity},
      {sessionId: 's', updatedAt: 1e20},
    ];

    expect({
      valid: cursors.map(before =>
        validateMessage({type: 'list_sessions', limit: 0, before: {...before, userId: 'other'}}),
      ),
      invalid: invalid.map(before => validateMessage({type: 'list_sessions', before})),
    }).toEqual({
      valid: cursors.map(before => ({valid: true, data: {type: 'list_sessions', limit: 0, before}})),
      invalid: invalid.map(() => ({valid: false, error: 'list_sessions before must be a valid cursor'})),
    });
  });
});
EOF
timeout 300 npm test -- --runTestsByPath src/transport/ws/listSessionsCursor.test.ts --runInBand"

